// Помощники «מה אני מחפש לקנות?» (/postbuyerrequest) для гостя (#da55b1). ПРОД, без записи:
// - POST …/rest/v1/demanded_business перехватывается и получает ПОДМЕНЁННЫЙ ответ (201 или ошибку) — в базу ничего не пишется;
// - все прочие не-GET запросы обрываются и собираются в ctl.unexpected;
// - service worker выключается (test.use serviceWorkers: 'block'), иначе page.route не видит запросы.
import { expect, Page, Request } from '@playwright/test';

export const LOAD = { timeout: 20_000 };
export const PATH = '/postbuyerrequest';
export const HEADING = 'מה אני מחפש לקנות?';
export const SUBMIT = 'פרסם בקשה';
export const SUCCESS = 'הבקשה פורסמה בהצלחה!';
export const ERROR = 'שגיאה בפרסום הבקשה, אנא נסה שנית.';
export const NO_ACCESS = 'הבקשה לא נמצאה, או שאין לך הרשאה לערוך אותה.';
export const FIELDS = [
  'כותרת הבקשה *',
  'קטגוריה',
  'אזור',
  'עיר',
  'תקציב מינימום',
  'תקציב מקסימום',
  'תיאור הבקשה',
  'שם ליצירת קשר',
  'טלפון ליצירת קשר *',
];
export const INPUT = {
  title: 'QA-AUTO buyer-request-guest',
  city: 'תל אביב',
  contact_name: 'QA-AUTO',
  contact_phone: '0501234567',
};

const isInsert = (r: Request) => r.method() === 'POST' && /\/rest\/v1\/demanded_business(\?|$)/.test(r.url());

export type Ctl = {
  /** Тела перехваченных POST demanded_business (в базу не дошли). */
  inserts: Record<string, unknown>[];
  /** Прочие не-GET запросы — оборваны. */
  unexpected: string[];
};

/**
 * Блок записи. reply = 'ok' → POST demanded_business получает 201 с «созданной» строкой
 * (по Accept: объект для .single(), иначе массив); число → такой статус ошибки (403 — как до исправления, #faaff9).
 */
export async function interceptWrites(page: Page, reply: 'ok' | number = 'ok'): Promise<Ctl> {
  const ctl: Ctl = { inserts: [], unexpected: [] };
  await page.route('**/*', async (route) => {
    const req = route.request();
    if (['GET', 'HEAD', 'OPTIONS'].includes(req.method())) return route.fallback();
    if (isInsert(req)) {
      const body = (req.postDataJSON() ?? {}) as Record<string, unknown>;
      ctl.inserts.push(body);
      if (reply !== 'ok') {
        return route.fulfill({
          status: reply,
          contentType: 'application/json',
          body: JSON.stringify({ code: '42501', message: 'new row violates row-level security policy (QA mock)' }),
        });
      }
      const row = { id: '00000000-0000-0000-0000-00000000da55', created_date: new Date().toISOString(), ...body };
      const single = (req.headers()['accept'] ?? '').includes('vnd.pgrst.object');
      return route.fulfill({ status: 201, contentType: 'application/json', body: JSON.stringify(single ? row : [row]) });
    }
    ctl.unexpected.push(`${req.method()} ${req.url()}`);
    return route.abort('blockedbyclient');
  });
  return ctl;
}

/** Гость открывает форму: без перехода на /auth, заголовок и кнопка на месте. */
export async function openAsGuest(page: Page) {
  await page.goto(PATH);
  await expect(page.getByRole('heading', { name: HEADING }), `заголовок «${HEADING}»`).toBeVisible(LOAD);
  await expect(page, 'гость остаётся на /postbuyerrequest (нет перехода на вход)').toHaveURL(/\/postbuyerrequest/);
  await expect(page.locator('#title'), 'поле «כותרת הבקשה» загрузилось').toBeVisible(LOAD);
}

export const submitButton = (page: Page) => page.getByRole('button', { name: SUBMIT, exact: true });

/** Заполнить минимально нужное (обязательные + город и имя). */
export async function fillRequest(page: Page) {
  await page.locator('#title').fill(INPUT.title);
  await page.locator('#city').fill(INPUT.city);
  await page.locator('#contact_name').fill(INPUT.contact_name);
  await page.locator('#contact_phone').fill(INPUT.contact_phone);
}
